insert into fx select k,gen_random_uuid() from unnest(array['capture','capture2','capture3','capture4']) k;
insert into fx select 'attachment-snapshot',snapshot_id from ezyvet_attachment_page_observations where run_id=(select id from fx where k='run') and ordinal=1;
insert into auth.users(id,email,raw_user_meta_data) values('db710000-0000-4000-8000-000000000003','original-dvm@example.test','{}'),('db710000-0000-4000-8000-000000000004','original-staff@example.test','{}');
insert into user_roles(user_id,role) values('db710000-0000-4000-8000-000000000003','DVM'),('db710000-0000-4000-8000-000000000004','STAFF') on conflict do nothing;
insert into fx select k,gen_random_uuid() from unnest(array['approve','approve2','approve3','ack','withdraw','abandon','ack-abandon','withdraw-abandon']) k;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db710000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select prepare_ezyvet_attachment_capture((select id from fx where k='capture'),(select id from fx where k='mapping'),(select id from fx where k='run'),1,1,(select id from fx where k='attachment-snapshot'),1,repeat('b',64));
