insert into data select 'claim1',claim_ezyvet_attachment_capture((select id from fx where k='capture'),'db710000-0000-4000-8000-000000000001');
insert into data select 'reserve1',reserve_ezyvet_attachment_original((select id from fx where k='capture'),'db710000-0000-4000-8000-000000000001',(select v#>>'{lease_id}' from data where k='claim1')::uuid,encode(sha256(convert_to('%PDF-test123','UTF8')),'hex'),'application/pdf',12,repeat('a',64),repeat('c',64));
