insert into data select 'ready2',complete_ezyvet_attachment_capture((select id from fx where k='capture2'),'db710000-0000-4000-8000-000000000001',(select v#>>'{lease_id}' from data where k='claim2')::uuid,(select v#>>'{intent,id}' from data where k='reserve2')::uuid,encode(sha256(convert_to('%PDF-test123','UTF8')),'hex'),'application/pdf',12);
reset role;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db710000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select prepare_ezyvet_attachment_capture((select id from fx where k='capture3'),(select id from fx where k='mapping'),(select id from fx where k='run'),1,1,(select id from fx where k='attachment-snapshot'),1,repeat('b',64));
reset role;set local role service_role;
insert into data select 'claim3',claim_ezyvet_attachment_capture((select id from fx where k='capture3'),'db710000-0000-4000-8000-000000000001');
insert into data select 'reserve3',reserve_ezyvet_attachment_original((select id from fx where k='capture3'),'db710000-0000-4000-8000-000000000001',(select v#>>'{lease_id}' from data where k='claim3')::uuid,encode(sha256(convert_to('%PDF-test123','UTF8')),'hex'),'application/pdf',12,repeat('a',64),repeat('c',64));
