insert into data select 'ready3',complete_ezyvet_attachment_capture((select id from fx where k='capture3'),'db710000-0000-4000-8000-000000000001',(select v#>>'{lease_id}' from data where k='claim3')::uuid,(select v#>>'{intent,id}' from data where k='reserve3')::uuid,encode(sha256(convert_to('%PDF-test123','UTF8')),'hex'),'application/pdf',12);
