set local role authenticated;select set_config('request.jwt.claims','{"sub":"db710000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into data select 'approved',approve_ezyvet_attachment_original((select id from fx where k='approve'),(select id from fx where k='pet'),(select v#>>'{request,capture,id}' from data where k='ready1')::uuid,(select v#>>'{request,capture,capture_hash}' from data where k='ready1'),1,null,'Reviewed original for explicit sharing',true);
insert into data select 'selection',jsonb_build_object('api_original_ids',jsonb_build_array(v#>'{record,id}')) from data where k='approved';
reset role;
-- FIXTURE_END
select throws_ok($$select release_preview_v9_internal((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','attachment@example.test',(select v from data where k='selection'))$$,'40001',null,'Missing acknowledgment cannot enter release');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db710000-0000-4000-8000-000000000003","role":"authenticated"}',true);
insert into data select 'acknowledged',acknowledge_ezyvet_attachment_original((select id from fx where k='ack'),(select id from fx where k='pet'),(select v#>>'{record,id}' from data where k='approved')::uuid,(select v#>>'{record,record_hash}' from data where k='approved'),(select v#>>'{record,capture_hash}' from data where k='approved'),true);
