select is((select v#>'{snapshot,api_originals,0,record}' from data where k='preview'),(select v->'record' from data where k='approved'),'Frozen exact7100 record projection');
select is((select v#>'{snapshot,api_originals,0,acknowledgment}' from data where k='preview'),(select v->'acknowledgment' from data where k='acknowledged'),'Single exact earliest acknowledgment');
select is((select v#>>'{snapshot,schema_version}' from data where k='preview'),'9','API-only package schema9');
select is(jsonb_array_length((select v#>'{snapshot,attachments}' from data where k='preview')),0,'API originals do not become patient documents');
select is((list_record_release_sources_v9((select id from fx where k='pet'))->>'policy_v9_accepted')::boolean,false,'Policy9 remains unaccepted');
select is(jsonb_array_length(list_record_release_sources_v9((select id from fx where k='pet'))->'api_original_ids'),1,'Acknowledged ready record is discoverable');
select is((select_all_record_release_sources_v9((select id from fx where k='pet'))#>'{selection,api_original_ids}'),(select v->'api_original_ids' from data where k='selection'),'Select-all includes explicit eligible original');
insert into fx values('release',gen_random_uuid());
select throws_ok($$select confirm_record_release((select id from fx where k='release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','attachment@example.test',(select v from data where k='selection'),(select v->'snapshot' from data where k='preview'),(select v->>'source_hash' from data where k='preview'),true)$$,'42501',null,'Unaccepted policy prevents confirmation');
reset role;
insert into record_release_policy(id,enabled,accepted_schema_version,accepted_at,accepted_by,acceptance_reference) values(true,true,9,now(),'Synthetic DVM','Local SQL only') on conflict(id) do update set enabled=true,accepted_schema_version=9,accepted_at=now();
set local role authenticated;
insert into data select 'release',to_jsonb(confirm_record_release((select id from fx where k='release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','attachment@example.test',(select v from data where k='selection'),(select v->'snapshot' from data where k='preview'),(select v->>'source_hash' from data where k='preview'),true));
select is((read_record_release((select id from fx where k='release'))->>'eligible')::boolean,true,'Confirmed schema9 is eligible');
reset role;
select is((select source_kind from record_release_sources where release_id=(select id from fx where k='release')),'api_original','Separate source registry family');
select lives_ok($$select verify_release_api_original((select v#>'{snapshot,api_originals,0}' from data where k='preview'),'1-ezyvet-original-701.pdf','application/pdf',convert_to('%PDF-test123','UTF8'),1)$$,'Exact decoded API original accepted');
select throws_ok($$select verify_release_api_original((select v#>'{snapshot,api_originals,0}' from data where k='preview'),'1-ezyvet-original-701.pdf','application/pdf',convert_to('%PDF-test456','UTF8'),1)$$,'23514',null,'Same-size substitution rejected');
select throws_ok($$select verify_release_api_original((select v#>'{snapshot,api_originals,0}' from data where k='preview'),'2-ezyvet-original-701.pdf','application/pdf',convert_to('%PDF-test123','UTF8'),1)$$,'23514',null,'Reordered filename rejected');
select throws_ok($$select verify_release_api_original((select v#>'{snapshot,api_originals,0}' from data where k='preview'),'1-ezyvet-original-701.pdf','image/png',convert_to('%PDF-test123','UTF8'),1)$$,'23514',null,'Wrong MIME rejected');
select throws_ok($$select verify_release_api_original((select jsonb_set(v#>'{snapshot,api_originals,0}','{acknowledgment,capture_hash}',to_jsonb(repeat('0',64))) from data where k='preview'),'1-ezyvet-original-701.pdf','application/pdf',convert_to('%PDF-test123','UTF8'),1)$$,'23514',null,'Wrong acknowledgment evidence rejected');
-- Extra acknowledgment is append-only clinical evidence, not a source mutation.
insert into user_roles(user_id,role) values('db710000-0000-4000-8000-000000000002','DVM');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db710000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select acknowledge_ezyvet_attachment_original(gen_random_uuid(),(select id from fx where k='pet'),(select v#>>'{record,id}' from data where k='approved')::uuid,(select v#>>'{record,record_hash}' from data where k='approved'),(select v#>>'{record,capture_hash}' from data where k='approved'),true);
select is(preview_record_release_v9((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','attachment@example.test',(select v from data where k='selection')),(select v from data where k='preview'),'Later acknowledgment preserves earliest frozen entry');
select is((read_record_release((select id from fx where k='release'))->>'eligible')::boolean,true,'Later acknowledgment does not invalidate release');
reset role;
update ezyvet_identity_heads set version=version+1 where resource in('animal','attachment');
select is(release_preview_v9_internal((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','attachment@example.test',(select v from data where k='selection')),(select v from data where k='preview'),'Provider head refresh preserves admitted original');
select is((release_read_internal((select id from fx where k='release'))->>'eligible')::boolean,true,'Provider head refresh does not invalidate API-only release');
savepoint replaced;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db710000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select approve_ezyvet_attachment_original((select id from fx where k='approve2'),(select id from fx where k='pet'),(select v#>>'{request,capture,id}' from data where k='ready2')::uuid,(select v#>>'{request,capture,capture_hash}' from data where k='ready2'),1,(select v#>>'{record,id}' from data where k='approved')::uuid,'Explicit replacement',true);
select is((read_record_release((select id from fx where k='release'))->>'eligible')::boolean,false,'Replacement invalidates pending release');
rollback to replaced;
savepoint withdrawn;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db710000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select withdraw_ezyvet_attachment_original((select id from fx where k='withdraw'),(select id from fx where k='pet'),(select v#>>'{record,id}' from data where k='approved')::uuid,(select v#>>'{record,record_hash}' from data where k='approved'),'Withdraw after review');
select is((read_record_release((select id from fx where k='release'))->>'eligible')::boolean,false,'Withdrawal invalidates pending release');
select is(jsonb_array_length(list_record_release_sources_v9((select id from fx where k='pet'))->'api_original_ids'),0,'Withdrawn record excluded from candidates');
rollback to withdrawn;
reset role;
select ok(not has_function_privilege('authenticated','public.get_release_api_original_context(text,uuid,uuid,uuid)','execute'),'Staff cannot get private byte locator');
select ok(has_function_privilege('service_role','public.get_release_api_original_context(text,uuid,uuid,uuid)','execute'),'Service can resolve exact prepared delivery context');
select ok(not has_function_privilege('anon','public.preview_record_release_v9(uuid,uuid,text,text,jsonb)','execute'),'Anonymous cannot preview');
select ok(not has_function_privilege('authenticated','public.release_api_original_entry(uuid)','execute'),'Private projection not callable');
select * from finish();rollback;
